window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6599ffe16839671d"]={"versions": [{"id": "FIG-6599ffe16839671d", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts der AUTOSAR E2E-Bibliotheksfunktion <code>E2E_P04mProtect()</code> innerhalb des E2E-Profils 4m (End-to-End Communication Protection Protocol). Es modelliert den Einzelschritt „Write SourceID“ zur Serialisierung der Quellkennung in das zu schützende Daten-Array.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätskontext</strong>: <code>E2E_P04mProtect()</code></li>\n<li><strong>Eingangsknoten (Initial Node)</strong>: Startpunkt der Ausführung des Einzelschritts.</li>\n<li><strong>Aktionszustand (Action State)</strong>: <code>Copy 28-bit SourceID to bytes Data[Offset+12...Offset+15] in Big Endian order</code>.</li>\n<li><strong>Endknoten (Activity Final Node)</strong>: Abschluss des Schritts.</li>\n<li><strong>Daten- und Pufferparameter</strong>: Quellidentifikator <code>SourceID</code> (28 Bit breit) sowie Zielpuffer <code>Data[]</code> mit Byte-Indizierung relativ zu <code>Offset</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt in den Teilschritt über den Initialknoten nach Funktionsaufruf bzw. vorhergehenden Schutzschritten.</li>\n<li>Ausführung der Schreibaktion: Die 28-Bit-Kennung <code>SourceID</code> wird in die vier Ziel-Bytes <code>Data[Offset+12]</code> bis <code>Data[Offset+15]</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) übertragen.</li>\n<li>Übergang über die gerichtete Kante zum Endknoten und Abschluss der Teilaktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß [PRS_E2E_00762] ist das dargestellte Verhalten für die Implementierung der Schutzfunktion <code>E2E_P04mProtect()</code> normativ bindend. Entwickler müssen beachten, dass die 28-Bit-SourceID über vier Bytes (32 Bit) serialisiert wird. Nachfolgende Schritte (insbesondere <code>Write Message Type</code> und <code>Write Message Result</code>) manipulieren die verbleibenden oberen 4 Bits des ersten Bytes <code>Data[Offset+12]</code>, weshalb bei der Bitmaskierung und Byte-Zuordnung die exakte Bitbelegung und Reihenfolge der Schritte strikt einzuhalten ist.</p>"}, {"id": "FIG-8da27e0b2b95ec74", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts der AUTOSAR E2E-Bibliotheksfunktion <code>E2E_P04mProtect()</code> innerhalb des E2E-Profils 4m (End-to-End Communication Protection Protocol). Es modelliert den Einzelschritt „Write SourceID“ zur Serialisierung der Quellkennung in das zu schützende Daten-Array.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivitätskontext</strong>: <code>E2E_P04mProtect()</code></li>\n<li><strong>Eingangsknoten (Initial Node)</strong>: Startpunkt der Ausführung des Einzelschritts.</li>\n<li><strong>Aktionszustand (Action State)</strong>: <code>Copy 28-bit SourceID to bytes Data[Offset+12...Offset+15] in Big Endian order</code>.</li>\n<li><strong>Endknoten (Activity Final Node)</strong>: Abschluss des Schritts.</li>\n<li><strong>Daten- und Pufferparameter</strong>: Quellidentifikator <code>SourceID</code> (28 Bit breit) sowie Zielpuffer <code>Data[]</code> mit Byte-Indizierung relativ zu <code>Offset</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt in den Teilschritt über den Initialknoten nach Funktionsaufruf bzw. vorhergehenden Schutzschritten.</li>\n<li>Ausführung der Schreibaktion: Die 28-Bit-Kennung <code>SourceID</code> wird in die vier Ziel-Bytes <code>Data[Offset+12]</code> bis <code>Data[Offset+15]</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) übertragen.</li>\n<li>Übergang über die gerichtete Kante zum Endknoten und Abschluss der Teilaktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß [PRS_E2E_00762] ist das dargestellte Verhalten für die Implementierung der Schutzfunktion <code>E2E_P04mProtect()</code> normativ bindend. Entwickler müssen beachten, dass die 28-Bit-SourceID über vier Bytes (32 Bit) serialisiert wird. Nachfolgende Schritte (insbesondere <code>Write Message Type</code> und <code>Write Message Result</code>) manipulieren die verbleibenden oberen 4 Bits des ersten Bytes <code>Data[Offset+12]</code>, weshalb bei der Bitmaskierung und Byte-Zuordnung die exakte Bitbelegung und Reihenfolge der Schritte strikt einzuhalten ist.</p>"}], "trans": [{"from": "FIG-6599ffe16839671d", "to": "FIG-8da27e0b2b95ec74", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
